import { test, expect } from '@playwright/test';

test.describe('Async Error with Retry Option', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/api/data');
  });

  test('should display retry option when async request fails', async ({ page }) => {
    // Intercept the API call with a failed response
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Verify error message is visible
    const errorMessage = page.getByText('Failed to load data');
    await expect(errorMessage).toBeVisible();

    // Verify retry button is visible and enabled
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify retry button is enabled
    await expect(retryButton).toBeEnabled();

    // Click retry button
    await retryButton.click();

    // Verify retry request is made
    const retryRequest = page.waitForResponse('**/api/data');
    await expect(retryRequest).toHaveRequested();

    // Verify success message is displayed after retry
    const successMessage = page.getByText('Data loaded successfully');
    await expect(successMessage).toBeVisible();

    // Verify data is displayed
    const dataList = page.getByRole('list');
    await expect(dataList).toBeVisible();

    // Verify data items are present
    const dataItems = page.locator('[data-testid="data-item"]');
    await expect(dataItems).toHaveCount(3);
  });

  test('should not display retry option when request is successful', async ({ page }) => {
    // Intercept the API call with a successful response
    await page.route('**/api/data', (route) => {
      route.continue();
    });

    // Verify success message is visible
    const successMessage = page.getByText('Data loaded successfully');
    await expect(successMessage).toBeVisible();

    // Verify retry button is not visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).not.toBeVisible();

    // Verify retry button is disabled
    await expect(retryButton).toBeDisabled();

    // Verify data is displayed
    const dataList = page.getByRole('list');
    await expect(dataList).toBeVisible();

    // Verify data items are present
    const dataItems = page.locator('[data-testid="data-item"]');
    await expect(dataItems).toHaveCount(3);
  });
});
